    public function rows(string $key,array $filters=[],int $perPage=50): LengthAwarePaginator { $perPage=max(25,min(100,$perPage));$page=max(1,(int)($filters['page']??request()->integer('page',1)));if($this->isDimension($key)){ $all=$this->dimensionAggregate($key,$filters);$items=collect(array_slice($all,($page-1)*$perPage,$perPage));return new Paginator($items,count($all),$perPage,$page,['path'=>request()->url(),'query'=>$filters]); }$query=$this->baseQuery($key,$filters);$p=$query?$query->paginate($perPage,['*'],'page',$page):new Paginator([],0,$perPage,$page);$items=collect();foreach($p->items() as $record)foreach($this->recordsFor($key,$record,$filters) as $row)$items->push($row);return new Paginator($items,$p->total(),$perPage,$page,['path'=>request()->url(),'query'=>$filters]); }
