    private function recordsFor(string $key,object $record,array $filters): iterable { if(isset(self::MOVEMENTS[$key])){foreach($this->movementRowsFor($record,$key,$filters) as $r)yield$r;return;}if($key==='bookings'){yield$this->bookingRow($record);return;}if($key==='group-umrah'){yield$this->groupRow($record);return;}if($key==='air'){yield$this->airRow($record);return;}if($key==='passengers'){foreach($this->passengerRowsForBooking((int)($record->booking_id??0),$filters) as $r)yield$r;return;}yield$this->mapRow($key,$record); }
