e(', ')?:$services->pluck('service_name')->filter()->implode(', ');$row['saudi_company']=$this->first($b,['saudi_company_name','saudi_company','saudi_company_id']);$row['pakistani_iata']=$this->first($b,['pakistani_iata_name','pakistani_iata','pakistani_iata_id']);$row['status']=$this->first($b,['status','workflow_status']);$row['branch']=$this->first($b,['branch_name','branch_id']);$row['agent']=$this->first($b,['agent_name','agent_id']);$row['salesperson']=$this->first($b,['salesperson_name','salesperson_id']);$row['action']=$this->action($id);return$row; }
    private function movementRowsFor(object $b,string $key,array $filters): array { $id=(int)($b->booking_id??$b->id??0);$event=str_contains($key,'check')?$this->orderedChildRows('booking_group_package_hotels',$id):$this->orderedChildRows('booking_group_package_flights',$id);$event=$event->filter(fn($x)=>$this->movementMatches($x,$key))->filter(fn($x)=>$this->dateInRange($this->movementDate($x,$key),$filters['from']??null,$filters['to']??null));$out=[];foreach($event as $x){$r=$this->blank($key);$p=$this->paxCounts($this->passengers->rows($id));$r['booking_no']=$id;$r['customer']=$this->first($b,['customer_name','customer','customer_id']);$r['total_pax']=array_sum($p);$r['adult']=$p['adult'];$r['child']=$p['child'];$r['infant']=$p['infant'];$r['flight']=$x->flight_number??'—';$r['sector']=trim((string)($x->from_code??$x->from??'')).'-'.trim((string)($x->to_code??$x->to??''));$r['departure']=$x->departure_date??'—';$r['arrival']=$x->arrival_date??'—';$r['hotel']=$x->hotel_name??'—';$r['check_in']=$x->check_in??'—';$r['check_out']=$x->check_out??'—';$r['nights']=$x->nights??'—';$r['package']=$this->first($b,['package_name','package_code']);$r['flight_sector']=$r['sector'];$r['transport']='—';$r['makkah_hotel']=stripos((string)($x->city??''),'makkah')!==false?($x->hotel_name??'—'):'—';$r['madinah_hotel']=stripos((string)($x->city??''),'madinah')!==false?($x->hotel_name??'—'):'—';$r['saudi_company']=$this->first($b,['saudi_company_name','saudi_company_id']);$r['pakistani_iata']=$this->first($b,['pakistani_iata_name','pakistani_iata_id']);$r['status']=$this->first($b,['status','workflow_status']);$r['branch']=$this->first($b,['branch_name','branch_id']);$r['agent_salesperson']=$this->first($b,['agent_name','salesperson_name','agent_id']);$r['action']=$this->action($id);$out[]=$r;}return$out; }
    private function movementMatches(object $x,string $key): bool { $city=strtolower((string)($x->city??''));return match($key){'makkah-checkin','makkah-checkout'=>str_contains($city,'makkah'),'madinah-checkin','madinah-checkout'=>str_contains($city,'madinah'),'arrival'=>in_array(strtolower((string)($x->segment_type??$x->type??'')),['arrival','inbound'],true),'departure'=>in_array(strtolower((string)($x->segment_type??$x->type??'')),['departure','outbound'],true),default=>true}; }
