    private function passengerRowsForBooking(int $id,array $filters): array { $out=[];foreach($this->passengers->rows($id) as $p){$row=$this->mapPassenger($p,$id);if(($filters['passenger']??'')!==''&&!str_contains(strtolower($row['passenger']),strtolower((string)$filters['passenger'])))continue;if(($filters['pax_type']??'')!==''&&strtolower((string)$row['pax_type'])!==strtolower((string)$filters['pax_type']))continue;$out[]=$row;}return$out; }
