    private function isDimension(string $key): bool { return in_array($key,['customers','suppliers','branches','agents','airlines','sectors'],true); }
    /** Aggregate only operational identities; child records are deduplicated at native service grain. */
    private function dimensionAggregate(string $key,array $filters): array
    {
        $aggregate=[];$bookings=$this->filteredQuery('bookings',$filters);
        foreach($bookings->cursor() as $booking){$id=(int)($booking->id??$booking->booking_id??0);$pax=$this->passengers->rows($id);$branch=$this->first($booking,['branch_name','branch_id']);$customer=$this->first($booking,['customer_name','customer','customer_id']);$agent=$this->first($booking,['agent_name','agent_id']);$sales=$this->first($booking,['salesperson_name','salesperson_id']);$name=match($key){'customers'=>$customer,'branches'=>$branch,'agents'=>(($filters['mode']??'agent')==='salesperson'?$sales:$agent),default=>null};
            if($key==='airlines'||$key==='sectors'){$services=$this->childRows('booking_services',$id);foreach($services as $service){$segments=$this->orderedChildRows('booking_itinerary_segments',(int)$service->id,'booking_service_id');foreach($segments as $segment){$air=$this->first($segment,['airline_code','airline_name','airline']);$sector=$this->normalSector($segment);if(($filters['airline']??'')!==''&&!str_contains(strtolower($air),strtolower((string)$filters['airline'])))continue;if(($filters['origin']??'')!==''&&!str_contains(strtolower((string)($segment->from??$segment->from_code??'')),strtolower((string)$filters['origin'])))continue;if(($filters['destination']??'')!==''&&!str_contains(strtolower((string)($segment->to??$segment->to_code??'')),strtolower((string)$filters['destination'])))continue;$name=$key==='airlines'?$air:$sector;if(!$name||$name==='—')continue;$ref=&$aggregate[$name];$ref['airline']=$key==='airlines'?$name:($ref['airline']??$air);$ref['sector']=$key==='sectors'?$name:($ref['sector']??$sector);$ref['ticket_groups'][$service->id]=true;$ref['booking_ids'][$id]=true;$ref['passenger_ids'][$id]=$pax->count();$ref['sectors'][$sector]=true;$ref['branches'][$branch]=true;$ref['latest_departure']=max((string)($ref['latest_departure']??''),(string)($segment->departure_at??$segment->departure_date??''));$ref['airlines'][$air]=true;$ref['service_status'][$service->id]=$this->ticketStatus((int)$service->id);unset($ref);}}continue;}
            if($key==='suppliers'){foreach($this->supplierSources($id) as $source){$vendor=$source['vendor'];if(!$vendor)continue;if(($filters['vendor']??'')!==''&&!str_contains(strtolower((string)$vendor),strtolower((string)$filters['vendor'])))continue;if(($filters['service_type']??'')!==''&&strtolower((string)$filters['service_type'])!==strtolower((string)$source['type']))continue;$ref=&$aggregate[$vendor];$ref['name']=$vendor;$ref['service_types'][$source['type']]=true;$ref['booking_ids'][$id]=true;$ref['air_ticket_groups']=($ref['air_ticket_groups']??0)+($source['type']==='air'?1:0);$ref['hotel_stays']=($ref['hotel_stays']??0)+($source['type']==='hotel'?1:0);$ref['visa_services']=($ref['visa_services']??0)+($source['type']==='visa'?1:0);$ref['transport_segments']=($ref['transport_segments']??0)+($source['type']==='transport'?1:0);$ref['group_umrah_services']=($ref['group_umrah_services']??0)+($source['type']==='group-umrah'?1:0);$ref['branches'][$branch]=true;$ref['last_activity_date']=max((string)($ref['last_activity_date']??''),(string)$source['date']);unset($ref);}continue;}
